#' Sequential Probability Ratio Test
#'
#' Wald's sequential probability ratio test after every observation, for a 
#' proportion, a mean or a difference in means with known SD, and the 
#' sequential one- and two-sample t-tests; optionally Whitehead's continuous 
#' triangular test, and truncation at a maximum sample size. Wald's 
#' approximations and exact (or simulated) operating characteristics, and the 
#' test applied to data in arrival order.
#' @param data .
#' @param dep .
#' @param group .
#' @param model .
#' @param p0 .
#' @param p1 .
#' @param mu0 .
#' @param mu1 .
#' @param delta1 .
#' @param sigma .
#' @param d1 .
#' @param tails .
#' @param alpha .
#' @param power .
#' @param boundary .
#' @param truncate .
#' @param nMax .
#' @param truncRule .
#' @param nsim .
#' @param seed .
#' @param ocTable .
#' @param pathTable .
#' @param pathPlot .
#' @param ocPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$oc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$llrPath} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ocPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
sprt <- function(
    data,
    dep = NULL,
    group = NULL,
    model = "binom",
    p0 = 0.2,
    p1 = 0.4,
    mu0 = 0,
    mu1 = 0.5,
    delta1 = 0.5,
    sigma = 1,
    d1 = 0.5,
    tails = "one",
    alpha = 0.05,
    power = 0.8,
    boundary = "wald",
    truncate = FALSE,
    nMax = 100,
    truncRule = "sign",
    nsim = 2000,
    seed = 1,
    ocTable = TRUE,
    pathTable = FALSE,
    pathPlot = TRUE,
    ocPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("sprt requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- sprtOptions$new(
        dep = dep,
        group = group,
        model = model,
        p0 = p0,
        p1 = p1,
        mu0 = mu0,
        mu1 = mu1,
        delta1 = delta1,
        sigma = sigma,
        d1 = d1,
        tails = tails,
        alpha = alpha,
        power = power,
        boundary = boundary,
        truncate = truncate,
        nMax = nMax,
        truncRule = truncRule,
        nsim = nsim,
        seed = seed,
        ocTable = ocTable,
        pathTable = pathTable,
        pathPlot = pathPlot,
        ocPlot = ocPlot)

    analysis <- sprtClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

